from sklearn.model_selection import GroupKFold, TimeSeriesSplit

def solve(data):
    if len(set(data['groups'])) < data['groupSplits']:
        return {'error': 'insufficient-groups', 'groupFolds': [], 'timeFolds': []}
    X = np.arange(len(data['groups'])).reshape(-1, 1)
    grouped = list(GroupKFold(n_splits=data['groupSplits']).split(X, groups=data['groups']))
    try:
        temporal = list(TimeSeriesSplit(n_splits=data['timeSplits'], gap=data['gap']).split(X))
    except ValueError:
        return {'error': 'invalid-time-split', 'groupFolds': [], 'timeFolds': []}
    group_reports, time_reports = [], []
    for train, valid in grouped:
        train_groups = set(data['groups'][i] for i in train)
        valid_groups = set(data['groups'][i] for i in valid)
        group_reports.append({'train': train.tolist(), 'valid': valid.tolist(),
                              'trainGroups': sorted(train_groups), 'validGroups': sorted(valid_groups),
                              'overlap': sorted(train_groups & valid_groups)})
    for train, valid in temporal:
        time_reports.append({'train': train.tolist(), 'valid': valid.tolist(),
                             'lastTrainTime': data['times'][int(train[-1])],
                             'firstValidTime': data['times'][int(valid[0])],
                             'actualGap': int(valid[0] - train[-1] - 1)})
    return {'error': None, 'groupFolds': group_reports, 'timeFolds': time_reports}

